import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, mix, vec3, color } from 'three/tsl';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Vector3 } = ctx.THREE;

  // Root group
  const root = new Group();

  // ---------- Backdrop Gradient ----------
  const bgGeom = new PlaneGeometry(7, 6);
  const bgMat = new MeshStandardNodeMaterial();
  const uvNode = uv();
  const gradColorTop = color('#0b0b10');
  const gradColorBottom = color('#14141a');
  bgMat.colorNode = mix(gradColorTop, gradColorBottom, uvNode.y);
  bgMat.roughness = 0.5;
  bgMat.metalness = 0;
  const bgMesh = new Mesh(bgGeom, bgMat);
  bgMesh.position.set(0, 0, -2.5);
  root.add(bgMesh);

  // ---------- Text ----------
  const headline = ctx.fontAtlas.createText('Inside the atelier', {
    fontSize: 68,
    color: '#e8ecf2',
    align: 'left',
  });
  headline.position.set(-1.6, 1.9, 0);
  root.add(headline);

  const captions = [
    'DIAL ROOM',
    'ESCAPEMENT BENCH',
    'CNC HALL',
    'FINISHING LAB',
    'ARCHIVE VAULT',
    'ASSEMBLY LINE ONE',
  ];

  const textObjects = [];

  captions.forEach((txt, idx) => {
    const txtObj = ctx.fontAtlas.createText(txt, {
      fontSize: 18,
      color: '#e8ecf2',
      align: 'left',
      letterSpacingPx: 0.08,
    });
    // Position each caption near its plate
    txtObj.position.set(-1.6, idx * 1.5 - 0.6, 0);
    root.add(txtObj);
    textObjects.push(txtObj);
  });

  // ---------- Image Plates ----------
  const plateGroup = new Group();
  const plateMaterials = [];
  const plateTextures = [];

  const imageUrl = config.imageUrl || '/prism-mock/home/nodes/feature-card.png';

  for (let i = 0; i < 6; i++) {
    const single = new Group();
    single.position.set(0.9, i * 1.5, 0);

    // Frame (ink bevel)
    const frameGeom = new PlaneGeometry(1.96, 1.26);
    const frameMat = new MeshStandardNodeMaterial();
    frameMat.color = new ctx.THREE.Color('#16161d');
    frameMat.roughness = 0.5;
    frameMat.metalness = 0.5;
    const frameMesh = new Mesh(frameGeom, frameMat);
    frameMesh.position.set(0, 0, -0.001);
    single.add(frameMesh);

    // Plate
    const plateGeom = new PlaneGeometry(1.9, 1.2);
    const plateMat = new MeshStandardNodeMaterial();
    plateMat.roughness = 0.6;
    plateMat.metalness = 0.1;
    plateMat.clearcoat = 0.1;
    const plateMesh = new Mesh(plateGeom, plateMat);
    plateMesh.position.set(0, 0, 0.001);
    single.add(plateMesh);

    // Load texture asynchronously, but keep function sync
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      plateMat.map = tex;
      plateMat.needsUpdate = true;
      plateTextures.push(tex);
    });

    plateMaterials.push(plateMat);
    plateGroup.add(single);
  }

  root.add(plateGroup);

  // ---------- Cinematic Primitive ----------
  const primitivesCleanup = [];
  if (config.cinematicPrimitives) {
    config.cinematicPrimitives.forEach((prim) => {
      const p = ctx.primitives[prim.name];
      if (p) {
        const instance = p(root, prim.params || {});
        primitivesCleanup.push(() => {
          if (instance && typeof instance.cleanup === 'function') instance.cleanup();
        });
      }
    });
  }

  // ---------- User Data ----------
  root.userData.handlers = {};

  root.userData.cleanup = () => {
    // Dispose materials
    plateMaterials.forEach((mat) => {
      if (mat && typeof mat.dispose === 'function') mat.dispose();
    });
    // Dispose textures
    plateTextures.forEach((tex) => {
      if (tex && typeof tex.dispose === 'function') tex.dispose();
    });
    // Dispose backdrop material
    if (bgMat && typeof bgMat.dispose === 'function') bgMat.dispose();
    // Dispose frame materials (already in plateMaterials)
    // Dispose text objects (handled by fontAtlas internally)
    // Kill any GSAP timelines (none created directly here)
    // Cleanup primitives
    primitivesCleanup.forEach((fn) => fn());
  };

  return root;
}
